const mqL=matchMedia('(prefers-color-scheme: light)');let PREF=document.documentElement.dataset.pref||'auto',ttT;
function setTheme(p,save){PREF=p;const eff=p=='auto'?(mqL.matches?'light':'dark'):p,d=document.documentElement;
 d.classList.add('tt');d.dataset.theme=eff;d.dataset.pref=p;clearTimeout(ttT);ttT=setTimeout(()=>d.classList.remove('tt'),800);
 $('meta[name=theme-color]').content=getComputedStyle(d).getPropertyValue('--bg').trim();
 if(save){try{localStorage.setItem('sh-theme',p)}catch(e){}}
 $$('#tp button').forEach(b=>b.classList.toggle('on',b.dataset.th==p))}
if(mqL.addEventListener)mqL.addEventListener('change',()=>{if(PREF=='auto')setTheme('auto')});
$$('#tp button').forEach(b=>b.onclick=()=>{setTheme(b.dataset.th,true);closeTp()});
const tp=$('#tp'),thb=$('#th');function closeTp(){tp.classList.remove('open');thb.setAttribute('aria-expanded','false')}
thb.onclick=e=>{e.stopPropagation();const o=!tp.classList.contains('open');tp.classList.toggle('open',o);thb.setAttribute('aria-expanded',o)};
addEventListener('click',e=>{if(!tp.contains(e.target))closeTp()});addEventListener('keydown',e=>{if(e.key=='Escape'){closeTp();document.body.classList.remove('mo')}});
