const stg=$('#stg');stg.insertAdjacentHTML('afterbegin',STORY.map((s,i)=>`<img src="${IMG[s[4]]}" alt="" class="${i?'':'on'}">`).join(''));
const simgs=$$('#stg img');
function paintStory(){
 $('#scnt').innerHTML=`<b>0${S+1}</b> / 0${N}`;
 $$('#seg button').forEach((b,i)=>b.classList.toggle('on',i==S));
 $('#gt').textContent=STORY[S][1];$('#sty').style.setProperty('--sc',STORY[S][0]);$('.gl i').style.background=STORY[S][0];
 $$('#sls .si').forEach((m,i)=>m.classList.toggle('on',i==S))}
function showStory(i,dir){const to=((i%N)+N)%N;if(to==S)return;const prev=S;S=to;
 stg.style.setProperty('--d',dir);simgs[prev].classList.remove('on');simgs[prev].classList.add('out');simgs[S].classList.remove('out');simgs[S].classList.add('on');
 setTimeout(()=>{if(!simgs[prev].classList.contains('on'))simgs[prev].classList.remove('out')},1400);paintStory()}
const nextS=()=>showStory(S+1,1),prevS=()=>showStory(S-1,-1);
$('#snext').onclick=nextS;$('#sprev').onclick=prevS;
addEventListener('keydown',e=>{if(e.key!='ArrowRight'&&e.key!='ArrowLeft')return;const t=document.activeElement&&document.activeElement.tagName;if(t=='INPUT'||t=='TEXTAREA')return;
 const r=$('#story').getBoundingClientRect();if(r.top<innerHeight*.65&&r.bottom>innerHeight*.35){e.preventDefault();e.key=='ArrowRight'?nextS():prevS()}});
let tx0=0,ty0=0;stg.addEventListener('touchstart',e=>{tx0=e.touches[0].clientX;ty0=e.touches[0].clientY},{passive:true});
stg.addEventListener('touchend',e=>{const t=e.changedTouches[0],dx=t.clientX-tx0,dy=t.clientY-ty0;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4)dx<0?nextS():prevS()},{passive:true});
function buildSeg(){$('#seg').innerHTML=STORY.map((s,i)=>`<button aria-label="${i+1}"></button>`).join('');$$('#seg button').forEach((b,i)=>b.onclick=()=>showStory(i,i>S?1:-1))}
