 lie:[66,-12, 46,-10, 0,-10, -36,-14, -72,-8, -34,-8, -70,-4, 30,-8, 14,-6, 26,-14, 8,-12],
 lieF:[64,-12, 44,-10, 0,-10, -30,-24, -62,-8, -34,-10, -70,-14, 52,-26, 80,-20, 22,-30, 10,-38],
 stumble:[52,-132, 36,-114, 0,-84, -16,-44, -30,0, 14,-46, 12,-4, 58,-110, 82,-120, 40,-84, 70,-80],
 reach:[0,-168, 0,-142, 0,-88, -5,-44, -7,0, 5,-44, 7,0, -12,-112, -14,-84, 18,-120, 34,-112],
