const wk=ph=>{const s=Math.sin(ph),c=Math.cos(ph),a=Math.max(0,c),b=Math.max(0,-c),bob=-3*(1-Math.abs(s));
 return [4,-168+bob, 2,-142+bob, 0,-88+bob, 12*s+3,-44-3*a, 26*s,-9*a, -12*s+3,-44-3*b, -26*s,-9*b, -9*s,-112+bob, -18*s,-84+bob+2*Math.max(0,s), 9*s,-112+bob, 18*s,-84+bob+2*Math.max(0,-s)]};
const eIO=t=>t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2,eIn=t=>t*t*t,eOut=t=>1-Math.pow(1-t,3);
function Person(g,o){
 const mk=(t,c)=>{const e=document.createElementNS(NS,t);if(c)e.setAttribute('class',c);g.appendChild(e);return e};
 const ar=mk('polyline','pb'),lr=mk('polyline','pb'),to=mk('polyline','pt'),ll=mk('polyline'),al=mk('polyline'),nk=mk('polyline','pn'),hd=mk('circle','phd');
 const brd=mk('circle','brd'),brb=mk('circle','brb'),brp=mk('circle','brp'),bre=[brd,brb,brp];
 const dots=o.sk?Array.from({length:KP},()=>{const c=mk('circle','pj');c.setAttribute('r',3.6);return c}):[];
 const P={v:{x:0,y:0,f:1},pose:POSE.stand.slice(),from:null,to:null,pt:1,pd:0,pe:eIO,w:0,wt:0,ph:0,tw:[],px:0,nw:false,ratio:0,bb:{x:0,y:0,w:0,h:0},br:true,brs:true};
 P.set=(n,d,e)=>{P.from=P.pose.slice();P.to=POSE[n];P.pt=0;P.pd=Math.max(d||.01,.01);P.pe=e||eIO};
 P.tween=(k,b,d,e)=>{P.tw=P.tw.filter(t=>t.k!=k);P.tw.push({k,a:P.v[k],b,t:0,d:Math.max(d,.01),e:e||eIO})};
 P.go=(x,d,opt)=>{opt=opt||{};P.nw=!!opt.nw;const dx=x-P.v.x;if(!opt.nw&&Math.abs(dx)>2)P.tween('f',dx>0?1:-1,.28);P.tween('x',x,d)};
 P.snap=(n,x,y,f)=>{P.pose=POSE[n].slice();P.pd=0;P.tw=[];P.v.x=x;P.v.y=y||0;P.v.f=f||1;P.px=x;P.w=0;P.nw=false};
 P.draw=dt=>{
  P.tw.forEach(t=>{t.t=Math.min(1,t.t+dt/t.d);P.v[t.k]=t.a+(t.b-t.a)*t.e(t.t)});P.tw=P.tw.filter(t=>t.t<1);
  if(P.pd){P.pt=Math.min(1,P.pt+dt/P.pd);const e=P.pe(P.pt);for(let i=0;i<22;i++)P.pose[i]=P.from[i]+(P.to[i]-P.from[i])*e;if(P.pt>=1)P.pd=0}
  const dx=P.v.x-P.px;P.px=P.v.x;const sp=dt>0?Math.abs(dx)/dt:0;P.wt=(!P.nw&&sp>10)?1:0;P.w+=(P.wt-P.w)*Math.min(1,dt*10);P.ph+=Math.abs(dx)/104*6.2832;
  const wp=wk(P.ph),w=P.w,f=P.v.f,sc=o.sc||1,X=[],Y=[];
  for(let i=0;i<KP;i++){const a=P.pose[2*i]*(1-w)+wp[2*i]*w,b=P.pose[2*i+1]*(1-w)+wp[2*i+1]*w;X.push(P.v.x+f*a*sc);Y.push(o.base-P.v.y*sc+b*sc)}
  const q=(...ix)=>ix.map(i=>X[i].toFixed(1)+','+Y[i].toFixed(1)).join(' ');
  ar.setAttribute('points',q(1,9,10));lr.setAttribute('points',q(2,5,6));to.setAttribute('points',q(1,2));ll.setAttribute('points',q(2,3,4));al.setAttribute('points',q(1,7,8));nk.setAttribute('points',q(0,1));
  const r=12*sc;hd.setAttribute('cx',X[0].toFixed(1));hd.setAttribute('cy',Y[0].toFixed(1));hd.setAttribute('r',r);
  dots.forEach((c,i)=>{c.setAttribute('cx',X[i].toFixed(1));c.setAttribute('cy',Y[i].toFixed(1))});
  {const bx=X[7]+(X[8]-X[7])*.8,by=Y[7]+(Y[8]-Y[7])*.8;bre.forEach(e=>{e.setAttribute('cx',bx.toFixed(1));e.setAttribute('cy',by.toFixed(1))});brd.setAttribute('r',(5.4*sc).toFixed(1));brb.setAttribute('r',(2.4*sc).toFixed(1));brp.setAttribute('r',(5*sc).toFixed(1));if(P.brs!==P.br){P.brs=P.br;bre.forEach(e=>e.style.display=P.br?'':'none')}}
  const x0=Math.min(...X)-6,x1=Math.max(...X)+6,y0=Math.min(...Y)-r-2,y1=Math.max(...Y)+3;
  P.bb={x:x0,y:y0,w:x1-x0,h:y1-y0};P.ratio=(x1-x0)/(y1-y0)};
 P.snap('stand',o.x||0,0,1);return P};
/* запускает кадровый цикл только пока блок на экране */
function Live(el,step){let vis=false,run=false,last=0;const loop=now=>{if(!vis){run=false;return}const dt=Math.min(.2,(now-last)/1000);last=now;if(!el.classList.contains('paused'))step(dt);requestAnimationFrame(loop)};
 new IntersectionObserver(es=>{vis=es[0].isIntersecting;if(vis&&!run){run=true;last=performance.now();requestAnimationFrame(loop)}},{threshold:.04}).observe(el)}
/* декор: лучи, звёзды, огни пути */
(function(){const r=$('#rays');for(let i=0;i<12;i++){const a=i*Math.PI/6,l=document.createElementNS(NS,'line');l.setAttribute('x1',84+Math.cos(a)*32);l.setAttribute('y1',84+Math.sin(a)*32);l.setAttribute('x2',84+Math.cos(a)*(i%2?40:46));l.setAttribute('y2',84+Math.sin(a)*(i%2?40:46));r.appendChild(l)}
 const s=$('#stars');for(let i=0;i<22;i++){const c=document.createElementNS(NS,'circle'),k=Math.sin(i*91.7)*43758.5453;const fx=k-Math.floor(k),k2=Math.sin(i*12.9)*9731.13,fy=k2-Math.floor(k2);c.setAttribute('cx',(40+fx*1000).toFixed(0));c.setAttribute('cy',(14+fy*120).toFixed(0));c.setAttribute('r',(.8+((i*7)%3)*.5).toFixed(1));c.style.animationDelay=(-(i%7)*.45)+'s';s.appendChild(c)}
 const p=$('#pth');for(let i=0;i<15;i++){const e=document.createElementNS(NS,'ellipse');e.setAttribute('cx',200+i*40);e.setAttribute('cy',437);e.setAttribute('rx',30);e.setAttribute('ry',8);e.style.setProperty('--i',i);p.appendChild(e)}})();

