const ALLC=['is-alert','is-sms','is-call','is-sos','is-hit','is-mmw','is-path','is-lamp','is-bed','is-ask','is-say','is-nobr'];
function loadScene(i,man){M.s=i;M.man=man;M.clk=0;M.ei=0;M.logs=[];M.fd=0;M.nt=null;M.ak=null;ALLC.forEach(c=>cls(c,0));hsc.classList.toggle('n',!!SC[i].night);
 M.ev=SC[i].ev().sort((a,b)=>a[0]-b[0]);M.rs=M.rt=8;M.bs=M.bpm=72;
 $$('#mtabs .mtab').forEach((b,k)=>{b.classList.toggle('on',k==i);b.querySelector('i').style.width='0'});$$('#fsc button').forEach((b,k)=>b.classList.toggle('on',k==i));$('#fsl').textContent=pick(SC[i].n);
 $('#ask1').textContent=pick('Всё ли в порядке?|Is everything OK?|Ist alles in Ordnung?');$('#say1').textContent=pick('Да, всё хорошо!|Yes, I’m fine!|Ja, mir geht’s gut!');
 while(M.ei<M.ev.length&&M.ev[M.ei][0]<=0)M.ev[M.ei++][1]();M.bs=M.bpm;mp.draw(0)}
