const cvc=$('#cvc'),cp=Person($('#cvp'),{base:292,sc:.85,x:120});
const CS={'STANDING':'var(--gr)','SITTING':'var(--gr)','LYING':'var(--ye)','FALL':'var(--re)','NO MOVEMENT':'var(--re)'};
let cvT=0,cvE=[],cvI=0,cvS='STANDING';
const cvSt=s=>{cvS=s;cvc.style.setProperty('--c',CS[s]);$('#cvst').textContent=s;$$('#chips span').forEach(c=>c.classList.toggle('on',c.dataset.s==s))};
const cvSeq=()=>[
 [0,()=>{cp.snap('stand',120,0,1);cvSt('STANDING')}],
 [.6,()=>cp.go(262,3.4)],
 [4.2,()=>{cp.set('sit',1.3);cvSt('SITTING')}],
 [8.2,()=>{cp.set('stand',1.2);cvSt('STANDING')}],
 [9.6,()=>cp.go(150,1.9)],
 [11.6,()=>cp.set('stumble',.35,eOut)],
 [11.95,()=>{cp.set('lieF',.5,eIn);cp.go(112,.85,{nw:true});cvSt('FALL')}],
 [13.2,()=>cvSt('LYING')],
 [14.4,()=>cvSt('NO MOVEMENT')]];
const cvLoad=()=>{cvT=0;cvI=0;cvE=cvSeq();while(cvI<cvE.length&&cvE[cvI][0]<=0)cvE[cvI++][1]()};
cvLoad();cp.draw(0);
Live(cvc,dt=>{cvT+=dt;while(cvI<cvE.length&&cvE[cvI][0]<=cvT)cvE[cvI++][1]();cp.draw(dt);
 const b=cp.bb,r=$('#cvbx');r.setAttribute('x',b.x);r.setAttribute('y',b.y);r.setAttribute('width',b.w);r.setAttribute('height',b.h);
 const t=$('#cvbt');t.setAttribute('x',b.x);t.setAttribute('y',b.y-7);t.textContent=cvS+(cvS=='NO MOVEMENT'?' · '+Math.max(0,Math.floor(cvT-14.4))+' s':'');
 $('#cvr').textContent=cp.ratio.toFixed(2);
 if(cvT>18.4)cvLoad()});
