const rp=(p,r)=>{r=r==null?7:r;let d='M'+p[0][0]+' '+p[0][1];for(let i=1;i<p.length-1;i++){const a=p[i-1],b=p[i],c=p[i+1],l1=Math.hypot(a[0]-b[0],a[1]-b[1]),l2=Math.hypot(c[0]-b[0],c[1]-b[1]),k1=Math.min(r,l1/2)/(l1||1),k2=Math.min(r,l2/2)/(l2||1);
 d+=` L${(b[0]+(a[0]-b[0])*k1).toFixed(1)} ${(b[1]+(a[1]-b[1])*k1).toFixed(1)} Q${b[0]} ${b[1]} ${(b[0]+(c[0]-b[0])*k2).toFixed(1)} ${(b[1]+(c[1]-b[1])*k2).toFixed(1)}`}
 const e=p[p.length-1];return d+` L${e[0]} ${e[1]}`};
const W=[];const wire=(k,devs,pts,r)=>W.push({k,devs,pts,r});
