const FS={el:null,ph:null,y:0};
function fsLabels(){$$('.fsb').forEach(b=>{const on=b.parentNode.classList.contains('is-fs'),t=pick(on?'Свернуть|Exit full screen|Verkleinern':'На весь экран|Full screen|Vollbild');b.title=t;b.setAttribute('aria-label',t)});psLabels()}
function fsClose(){const el=FS.el;if(!el)return;FS.el=null;el.classList.remove('is-fs');document.body.classList.remove('fsx');if(FS.ph)FS.ph.remove();
 try{if(document.fullscreenElement){const p=document.exitFullscreen();if(p&&p.catch)p.catch(()=>{})}if(screen.orientation&&screen.orientation.unlock)screen.orientation.unlock()}catch(e){}
 scrollTo(0,FS.y);fsLabels()}
function fsOpen(el){if(FS.el)fsClose();const r=el.getBoundingClientRect(),ph=document.createElement('div');ph.style.height=r.height+'px';ph.style.order=getComputedStyle(el).order;el.parentNode.insertBefore(ph,el);
 FS.el=el;FS.ph=ph;FS.y=scrollY;el.classList.add('is-fs');document.body.classList.add('fsx');fsLabels();
 try{const p=el.requestFullscreen&&el.requestFullscreen();if(p&&p.then)p.then(()=>{try{screen.orientation.lock('landscape').catch(()=>{})}catch(e){}}).catch(()=>{})}catch(e){}}
$$('.fsb').forEach(b=>b.onclick=()=>{const el=b.parentNode;FS.el===el?fsClose():fsOpen(el)});
addEventListener('keydown',e=>{if(e.key=='Escape'&&FS.el)fsClose()});
document.addEventListener('fullscreenchange',()=>{if(FS.el&&!document.fullscreenElement)fsClose()});
