 $('#sls').innerHTML=STORY.map((s,i)=>`<div class="si ${i==S?'on':''}"><small>0${i+1} / 0${N} · ${s[1]}</small><h3>${pick(s[2])}</h3><p>${pick(s[3])}</p></div>`).join('');
