 $('#tm').innerHTML=CONFIG.team.map((m,i)=>`<div class="c" style="--ph:url('${encodeURI(ASSETS.people[i]||'')}')"><b>0${i+1}</b><h3>${pick(m[0])}</h3><p>${pick(m[1])}</p></div>`).join('');
 $$('#tm .c').forEach((c,i)=>{if(!ASSETS.people[i])return;const im=new Image();im.onload=()=>c.classList.add('ph');im.src=encodeURI(ASSETS.people[i])});
