 $('#lim').innerHTML=items(CONFIG.limits);$('#nxt').innerHTML=items(CONFIG.next);
 const f=CONFIG.falseAlarms,mx=Math.max(...f.map(v=>v||0),1),ok=f[0]!=null&&f[3]!=null,r=ok&&f[3]>0?+(f[0]/f[3]).toFixed(1):null;
 $('#bars').innerHTML=f.map((v,i)=>`<div class="bar ${i==3?'last':''}"><span>${pick(CONFIG.labels[i])}</span><div><i data-w="${v==null?0:v/mx*100}" style="width:${v==null||!bi?0:v/mx*100}%"></i></div><b>${v==null?'—':v}</b></div>`).join('');
