function setLive(i){LV=i;const s=LIVE[i],c=$('#lv');c.style.setProperty('--c',s[1]);$('#lvs').textContent=s[0];$('#lvb').style.width=s[2]+'%';liveText();const from=lvShown,to=s[2],t0=performance.now();(function n(now){const p=cl((now-t0)/1400,0,1),e=1-Math.pow(1-p,3);lvShown=Math.round(from+(to-from)*e);$('#lvn').textContent=lvShown;if(p<1)requestAnimationFrame(n)})(t0)}
