/* smooth scroll (desktop wheel only; touch and reduced-motion stay native) */
const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,fine=matchMedia('(hover:hover) and (pointer:fine)').matches,mxs=()=>document.documentElement.scrollHeight-innerHeight;
let tg=0,cu=0,own=false;
const go=y=>{y=cl(y,0,mxs());if(reduce||!fine)scrollTo({top:y,behavior:reduce?'auto':'smooth'});else tg=y};
if(!reduce&&fine){addEventListener('wheel',e=>{if(e.ctrlKey||!document.body.classList.contains('go')||document.body.classList.contains('mo')||document.body.classList.contains('fsx'))return;e.preventDefault();tg=cl(tg+e.deltaY,0,mxs())},{passive:false});
 addEventListener('scroll',()=>{if(!own){tg=cu=scrollY}})}
