 const sc=$('.scrub'),r=sc.getBoundingClientRect(),p=cl((vh*.85-r.top)/(r.height+vh*.4),0,1),ws=sc.querySelectorAll('.sw2');ws.forEach((w,i)=>w.style.opacity=.16+.84*cl(p*ws.length*1.15-i,0,1));
 $('.b1').style.translate=`0 ${y*.12}px`;{const o=$('#orb');if(o&&y<vh*1.3)o.style.transform=`translate(${(px/innerWidth-.5)*-26}px,${(py/innerHeight-.5)*-20+y*.06}px)`}
 px+=(mx0-px)*.15;py+=(my0-py)*.15;$('#pv').style.left=px+24+'px';$('#pv').style.top=py-120+'px';
