/* loader */
const D=reduce?900:3100,ease=p=>p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;
let fin=0;function finish(){if(fin)return;fin=1;setTimeout(()=>{$('#ld').classList.add('out');setTimeout(()=>{$('#ld').classList.add('done');document.body.classList.add('go');rev();startLive();setTimeout(()=>$('#ld').remove(),1500)},380)},300)}
