 if(v=='eli'){Pth('M14 110H286');Pth('M150 46V110')}
 /* мебель */
 R(158,128,30,22,'hf',2);Pth('M173 128v22');
 if(v!='lite'){R(36,190,44,16,'hf',6);Pth('M40 206v4M76 206v4');R(212,194,46,14,'hf',5);R(252,182,9,26,'hf',4);R(238,128,26,20,'hf',2)}
